[metadata] {"type": "create", "filePath": "/app/output/poster.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<title>Frontier AI Models Compared - Infographic</title>
<style>
  :root {
    --bg-deep: #0b0d14;
    --bg-card: #141820;
    --bg-section: #1a1e28;
    --text-primary: #e8ecf1;
    --text-secondary: #939aa8;
    --text-muted: #636b7a;
    --accent-blue: #3b82f6;
    --accent-teal: #14b8a6;
    --accent-amber: #f59e0b;
    --accent-rose: #f43f5e;
    --accent-purple: #8b5cf6;
    --accent-cyan: #06b6d4;
    --border: #252a36;
    --stat-blue: #2563eb;
    --stat-teal: #0d9488;
    --stat-amber: #d97706;
    --stat-rose: #e11d48;
  }

  * { margin: 0; padding: 0; box-sizing: border-box; }

  body {
    width: 3508px;
    background: var(--bg-deep);
    color: var(--text-primary);
    font-family: 'Inter', 'Segoe UI', system-ui, -apple-system, sans-serif;
    line-height: 1.4;
    -webkit-font-smoothing: antialiased;
    overflow-x: hidden;
  }

  .poster {
    padding: 100px 120px 80px 120px;
    display: flex;
    flex-direction: column;
    gap: 60px;
  }

  /* ── HEADER ── */
  .header {
    display: flex;
    justify-content: space-between;
    align-items: flex-start;
    padding-bottom: 50px;
    border-bottom: 1px solid var(--border);
  }

  .header-left { max-width: 55%; }
  .header-left h1 {
    font-size: 96px;
    font-weight: 800;
    letter-spacing: -0.03em;
    line-height: 1.05;
    color: #fff;
    margin-bottom: 16px;
  }
  .header-left h1 span { color: var(--accent-blue); }
  .header-left .subtitle {
    font-size: 32px;
    color: var(--text-secondary);
    font-weight: 400;
    letter-spacing: -0.01em;
    margin-bottom: 8px;
  }
  .header-left .source {
    font-size: 22px;
    color: var(--text-muted);
    font-weight: 400;
  }

  /* ── CALLOUT STATS ── */
  .callout-stats {
    display: flex;
    gap: 28px;
    flex-wrap: wrap;
  }

  .stat-card {
    background: var(--bg-card);
    border: 1px solid var(--border);
    border-radius: 18px;
    padding: 36px 44px;
    min-width: 260px;
    text-align: center;
    position: relative;
    overflow: hidden;
  }

  .stat-card::before {
    content: '';
    position: absolute;
    top: 0; left: 0; right: 0;
    height: 4px;
  }
  .stat-card.blue::before { background: var(--accent-blue); }
  .stat-card.teal::before { background: var(--accent-teal); }
  .stat-card.amber::before { background: var(--accent-amber); }
  .stat-card.rose::before { background: var(--accent-rose); }

  .stat-value {
    font-size: 68px;
    font-weight: 800;
    letter-spacing: -0.03em;
    line-height: 1;
    margin-bottom: 8px;
  }
  .stat-card.blue .stat-value { color: var(--accent-blue); }
  .stat-card.teal .stat-value { color: var(--accent-teal); }
  .stat-card.amber .stat-value { color: var(--accent-amber); }
  .stat-card.rose .stat-value { color: var(--accent-rose); }

  .stat-label {
    font-size: 22px;
    font-weight: 600;
    color: var(--text-primary);
    margin-bottom: 6px;
  }
  .stat-unit {
    font-size: 18px;
    color: var(--text-muted);
    font-weight: 400;
  }

  /* ── SECTION TITLES ── */
  .section-title {
    display: flex;
    align-items: center;
    gap: 18px;
    margin-bottom: 28px;
  }
  .section-title .num {
    width: 52px; height: 52px;
    border-radius: 12px;
    background: var(--accent-blue);
    color: #fff;
    font-size: 24px;
    font-weight: 700;
    display: flex;
    align-items: center;
    justify-content: center;
    flex-shrink: 0;
  }
  .section-title h2 {
    font-size: 48px;
    font-weight: 700;
    letter-spacing: -0.02em;
    color: #fff;
  }
  .section-title .sub {
    font-size: 22px;
    color: var(--text-secondary);
    font-weight: 400;
    margin-left: 12px;
  }

  /* ── HERO TRADE-OFF ── */
  .hero-section {
    background: var(--bg-section);
    border: 1px solid var(--border);
    border-radius: 24px;
    padding: 60px 50px 50px 50px;
    position: relative;
  }

  .hero-section .highlight {
    background: linear-gradient(135deg, rgba(59,130,246,0.12), rgba(20,184,166,0.08));
    border: 1px solid rgba(59,130,246,0.2);
    border-radius: 14px;
    padding: 22px 32px;
    margin-bottom: 36px;
    font-size: 24px;
    color: var(--text-secondary);
    line-height: 1.5;
  }
  .hero-section .highlight strong { color: #fff; }

  #bubble-chart {
    width: 100%;
    height: auto;
    display: block;
  }

  /* ── CHART SECTIONS ── */
  .chart-section {
    background: var(--bg-section);
    border: 1px solid var(--border);
    border-radius: 24px;
    padding: 50px 50px 40px 50px;
  }

  .chart-section .chart-title {
    font-size: 36px;
    font-weight: 700;
    color: #fff;
    margin-bottom: 8px;
  }
  .chart-section .chart-desc {
    font-size: 22px;
    color: var(--text-secondary);
    margin-bottom: 32px;
  }

  /* AntV Infographic containers */
  .infographic-container {
    width: 100%;
    min-height: 850px;
  }

  /* ── INSIGHTS ── */
  .insights-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 24px;
  }

  .insight-card {
    background: var(--bg-card);
    border: 1px solid var(--border);
    border-radius: 16px;
    padding: 32px 36px;
    display: flex;
    align-items: flex-start;
    gap: 20px;
  }

  .insight-icon {
    width: 56px; height: 56px;
    border-radius: 12px;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 28px;
    flex-shrink: 0;
  }
  .insight-icon.blue { background: rgba(59,130,246,0.15); color: var(--accent-blue); }
  .insight-icon.teal { background: rgba(20,184,166,0.15); color: var(--accent-teal); }
  .insight-icon.amber { background: rgba(245,158,11,0.15); color: var(--accent-amber); }
  .insight-icon.rose { background: rgba(244,63,94,0.15); color: var(--accent-rose); }

  .insight-content h3 {
    font-size: 28px;
    font-weight: 700;
    color: #fff;
    margin-bottom: 8px;
  }
  .insight-content p {
    font-size: 22px;
    color: var(--text-secondary);
    line-height: 1.5;
  }
  .insight-content .model-name { color: var(--accent-blue); font-weight: 600; }

  /* ── METHODOLOGY ── */
  .methodology-section {
    background: var(--bg-section);
    border: 1px solid var(--border);
    border-radius: 18px;
    padding: 40px 50px;
  }
  .methodology-section h3 {
    font-size: 28px;
    font-weight: 700;
    color: #fff;
    margin-bottom: 14px;
  }
  .methodology-section p {
    font-size: 22px;
    color: var(--text-secondary);
    line-height: 1.6;
  }
  .methodology-section .evals {
    display: flex;
    flex-wrap: wrap;
    gap: 12px;
    margin-top: 18px;
  }
  .eval-tag {
    background: rgba(59,130,246,0.1);
    border: 1px solid rgba(59,130,246,0.2);
    border-radius: 8px;
    padding: 8px 18px;
    font-size: 18px;
    color: var(--accent-blue);
    font-weight: 500;
    white-space: nowrap;
  }

  /* ── FOOTER ── */
  .footer {
    text-align: center;
    padding-top: 30px;
    border-top: 1px solid var(--border);
    font-size: 20px;
    color: var(--text-muted);
  }
</style>
</head>
<body>
<div class="poster">

  <!-- HEADER -->
  <div class="header">
    <div class="header-left">
      <h1>Frontier AI Models<br><span>Compared</span></h1>
      <div class="subtitle">Intelligence &middot; Speed &middot; Cost</div>
      <div class="source">Based on the Artificial Analysis Intelligence Index v4.0 — 10 independent evaluations</div>
    </div>
  </div>

  <!-- CALLOUT STATS -->
  <div class="callout-stats">
    <div class="stat-card blue">
      <div class="stat-value">57</div>
      <div class="stat-label">Intelligence Score</div>
      <div class="stat-unit">AA Index — 2 models tied</div>
    </div>
    <div class="stat-card teal">
      <div class="stat-value">206</div>
      <div class="stat-label">Fastest Speed</div>
      <div class="stat-unit">tokens/sec — gpt-oss-120B</div>
    </div>
    <div class="stat-card amber">
      <div class="stat-value">$0.30 → $10.00</div>
      <div class="stat-label">Price Range</div>
      <div class="stat-unit">per million tokens</div>
    </div>
    <div class="stat-card rose">
      <div class="stat-value">33×</div>
      <div class="stat-label">Cost Multiplier</div>
      <div class="stat-unit">Cheapest to most expensive</div>
    </div>
  </div>

  <!-- HERO: TRADE-OFF ANALYSIS -->
  <div class="hero-section">
    <div style="display:flex;align-items:center;gap:18px;margin-bottom:20px;">
      <div class="num" style="background:var(--accent-teal);">★</div>
      <h2 style="font-size:48px;font-weight:700;color:#fff;letter-spacing:-0.02em;">The Intelligence–Speed–Cost Trade-Off</h2>
    </div>
    <div class="highlight">
      <strong>The fastest model isn't the smartest.</strong> The cheapest models aren't the fastest. And the smartest models come at a premium. There is no single "best" model — the right choice depends on what you optimize for.<br>
      <span style="color:var(--text-muted);font-size:20px;">Bubble size = cost. Hover to identify models.</span>
    </div>
    <div id="bubble-chart-container"></div>
  </div>

  <!-- INTELLIGENCE RANKINGS -->
  <div class="chart-section">
    <div class="chart-title">Intelligence Rankings</div>
    <div class="chart-desc">Scores from the Artificial Analysis Intelligence Index v4.0 — aggregating 10 benchmarks across coding, agentic tasks, knowledge, and reasoning</div>
    <div id="infographic-intelligence" class="infographic-container"></div>
  </div>

  <!-- SPEED COMPARISON -->
  <div class="chart-section">
    <div class="chart-title">Output Speed Comparison</div>
    <div class="chart-desc">Tokens generated per second — note that the fastest models are not the most intelligent</div>
    <div id="infographic-speed" class="infographic-container"></div>
  </div>

  <!-- PRICING LANDSCAPE -->
  <div class="chart-section">
    <div class="chart-title">Pricing Landscape</div>
    <div class="chart-desc">USD per 1 million tokens (blended input/output). A dramatic 33× spread from $0.30 to $10.00.</div>
    <div id="infographic-pricing" class="infographic-container"></div>
  </div>

  <!-- KEY INSIGHTS -->
  <div>
    <div class="section-title">
      <div class="num">◆</div>
      <h2>Key Trade-Off Insights</h2>
    </div>
    <div class="insights-grid">
      <div class="insight-card">
        <div class="insight-icon blue">S1</div>
        <div class="insight-content">
          <h3>Best Overall Intelligence</h3>
          <p><span class="model-name">Gemini 3.1 Pro Preview</span> and <span class="model-name">GPT-5.4</span> tied at 57 — but at mid-to-high cost ($4.50–$5.60 per 1M tokens) and moderate speed (72–129 tok/s).</p>
        </div>
      </div>
      <div class="insight-card">
        <div class="insight-icon teal">S2</div>
        <div class="insight-content">
          <h3>Best Value</h3>
          <p><span class="model-name">gpt-oss-120B</span> offers the fastest output (206 tok/s) and lowest price ($0.30) — but ranks last in intelligence (score 33). Speed doesn't equal smarts.</p>
        </div>
      </div>
      <div class="insight-card">
        <div class="insight-icon amber">S3</div>
        <div class="insight-content">
          <h3>Balanced Pick</h3>
          <p><span class="model-name">Gemini 3 Flash</span> lands in the sweet spot: intelligence score of 46, 149 tok/s output speed, and just $1.10 per 1M tokens — a compelling middle ground.</p>
        </div>
      </div>
      <div class="insight-card">
        <div class="insight-icon rose">S4</div>
        <div class="insight-content">
          <h3>Premium Tier</h3>
          <p><span class="model-name">Claude Opus 4.6</span> delivers 53 intelligence (third overall), but is the slowest at 40 tok/s and most expensive at $10.00 per 1M tokens. Quality has a price.</p>
        </div>
      </div>
    </div>
  </div>

  <!-- METHODOLOGY -->
  <div class="methodology-section">
    <h3>About the Index</h3>
    <p>The Artificial Analysis Intelligence Index v4.0 incorporates 10 independent evaluations spanning coding, agentic tasks, scientific reasoning, knowledge accuracy, hallucination resistance, and instruction following. All measurements are conducted independently by Artificial Analysis using standardized conditions.</p>
    <div class="evals">
      <span class="eval-tag">GDPval-AA</span>
      <span class="eval-tag">τ²-Bench Telecom</span>
      <span class="eval-tag">Terminal-Bench Hard</span>
      <span class="eval-tag">SciCode</span>
      <span class="eval-tag">AA-LCR</span>
      <span class="eval-tag">AA-Omniscience</span>
      <span class="eval-tag">IFBench</span>
      <span class="eval-tag">Humanity's Last Exam</span>
      <span class="eval-tag">GPQA Diamond</span>
      <span class="eval-tag">CritPt</span>
    </div>
  </div>

  <!-- FOOTER -->
  <div class="footer">
    Data: Artificial Analysis Intelligence Index v4.0 &middot; artificialanalysis.ai &middot; Measurements conducted independently under standardized conditions
  </div>

</div>

<script src="/app/vendor/infographic.min.js"></script>
<script>
// ══════════════════════════════════════════════
// DATA
// ══════════════════════════════════════════════
const models = [
  { name: 'Gemini 3.1 Pro Preview',  int: 57, speed: 129, price: 4.50, color: '#3b82f6', short: 'Gemini 3.1 Pro' },
  { name: 'GPT-5.4 (xhigh)',         int: 57, speed: 72,  price: 5.60, color: '#14b8a6', short: 'GPT-5.4' },
  { name: 'Claude Opus 4.6 (max)',   int: 53, speed: 40,  price: 10.00,color: '#f59e0b', short: 'Claude Opus 4.6' },
  { name: 'Muse Spark',              int: 52, speed: null,price: null, color: '#8b5cf6', short: 'Muse Spark' },
  { name: 'Claude Sonnet 4.6 (max)', int: 52, speed: 48,  price: 6.00, color: '#f59e0b', short: 'Claude Sonnet 4.6' },
  { name: 'GLM-5.1',                 int: 51, speed: 40,  price: 2.10, color: '#ec4899', short: 'GLM-5.1' },
  { name: 'Grok 4.20 0309 v2',       int: 49, speed: 162, price: 3.00, color: '#06b6d4', short: 'Grok 4.20' },
  { name: 'Gemini 3 Flash',          int: 46, speed: 149, price: 1.10, color: '#3b82f6', short: 'Gemini 3 Flash' },
  { name: 'DeepSeek V3.2',           int: 42, speed: 31,  price: 0.30, color: '#10b981', short: 'DeepSeek V3.2' },
  { name: 'NVIDIA Nemotron 3 Super', int: 36, speed: 193, price: 0.40, color: '#84cc16', short: 'Nemotron 3' },
  { name: 'gpt-oss-120B (high)',     int: 33, speed: 206, price: 0.30, color: '#f97316', short: 'gpt-oss-120B' },
];

// ══════════════════════════════════════════════
// BUBBLE CHART (Hero Trade-Off)
// ══════════════════════════════════════════════
function drawBubbleChart() {
  const container = document.getElementById('bubble-chart-container');
  const W = container.clientWidth || 3260;
  const H = 1600;
  const pad = { top: 60, right: 200, bottom: 100, left: 100 };
  const pw = W - pad.left - pad.right;
  const ph = H - pad.top - pad.bottom;

  const svgNS = 'http://www.w3.org/2000/svg';
  const svg = document.createElementNS(svgNS, 'svg');
  svg.setAttribute('viewBox', `0 0 ${W} ${H}`);
  svg.setAttribute('width', W);
  svg.setAttribute('height', H);
  svg.style.display = 'block';
  svg.style.width = '100%';
  svg.style.height = 'auto';
  svg.style.fontFamily = "'Inter','Segoe UI',system-ui,sans-serif";

  // Chart area background
  const chartBg = document.createElementNS(svgNS, 'rect');
  chartBg.setAttribute('x', pad.left);
  chartBg.setAttribute('y', pad.top);
  chartBg.setAttribute('width', pw);
  chartBg.setAttribute('height', ph);
  chartBg.setAttribute('fill', '#11161f');
  chartBg.setAttribute('rx', '10');
  svg.appendChild(chartBg);

  // Grid lines
  for (let yi = 30; yi <= 60; yi += 5) {
    const y = pad.top + ph - ((yi - 30) / 30) * ph;
    const line = document.createElementNS(svgNS, 'line');
    line.setAttribute('x1', pad.left); line.setAttribute('x2', pad.left + pw);
    line.setAttribute('y1', y); line.setAttribute('y2', y);
    line.setAttribute('stroke', yi === 30 ? '#252a36' : '#1c212b');
    line.setAttribute('stroke-width', yi === 30 ? '2' : '1');
    svg.appendChild(line);
    // Y label
    const text = document.createElementNS(svgNS, 'text');
    text.setAttribute('x', pad.left - 16);
    text.setAttribute('y', y + 8);
    text.setAttribute('text-anchor', 'end');
    text.setAttribute('fill', '#636b7a');
    text.setAttribute('font-size', '22');
    text.textContent = yi;
    svg.appendChild(text);
  }
  for (let xi = 0; xi <= 220; xi += 50) {
    const x = pad.left + (xi / 220) * pw;
    const line = document.createElementNS(svgNS, 'line');
    line.setAttribute('x1', x); line.setAttribute('x2', x);
    line.setAttribute('y1', pad.top); line.setAttribute('y2', pad.top + ph);
    line.setAttribute('stroke', xi === 0 ? '#252a36' : '#1c212b');
    line.setAttribute('stroke-width', xi === 0 ? '2' : '1');
    svg.appendChild(line);
