  }

  // Axis labels
  function addAxisLabel(text, x, y, rotate) {
    const t = document.createElementNS(svgNS, 'text');
    t.setAttribute('x', x); t.setAttribute('y', y);
    t.setAttribute('fill', '#939aa8');
    t.setAttribute('font-size', '26');
    t.setAttribute('font-weight', '600');
    t.setAttribute('text-anchor', 'middle');
    if (rotate) t.setAttribute('transform', `rotate(-90,${x},${y})`);
    t.textContent = text;
    svg.appendChild(t);
  }
  addAxisLabel('Output Speed (tokens/sec) →', pad.left + pw/2, pad.top + ph + 80);
  addAxisLabel('Intelligence Score →', 36, pad.top + ph/2, true);

  // Quadrant labels
  function addQLabel(text, x, y, opacity) {
    const t = document.createElementNS(svgNS, 'text');
    t.setAttribute('x', x); t.setAttribute('y', y);
    t.setAttribute('fill', '#636b7a');
    t.setAttribute('font-size', '22');
    t.setAttribute('font-weight', '500');
    t.setAttribute('text-anchor', 'middle');
    t.setAttribute('opacity', opacity || 0.6);
    t.setAttribute('font-style', 'italic');
    t.textContent = text;
    svg.appendChild(t);
  }
  addQLabel('Smart & Slow', pad.left + pw*0.15, pad.top + ph*0.15);
  addQLabel('Smart & Fast', pad.left + pw*0.85, pad.top + ph*0.15);
  addQLabel('Budget & Slow', pad.left + pw*0.15, pad.top + ph*0.88);
  addQLabel('Fast & Affordable', pad.left + pw*0.85, pad.top + ph*0.88);

  // Draw bubbles for models with complete data
  const bubbleModels = models.filter(m => m.speed !== null && m.price !== null);
  const priceMin = 0.30, priceMax = 10.00;

  bubbleModels.forEach(m => {
    const cx = pad.left + (m.speed / 220) * pw;
    const cy = pad.top + ph - ((m.int - 30) / 30) * ph;
    const r = 24 + Math.sqrt((m.price - priceMin) / (priceMax - priceMin)) * 64;

    // Bubble
    const circle = document.createElementNS(svgNS, 'circle');
    circle.setAttribute('cx', cx);
    circle.setAttribute('cy', cy);
    circle.setAttribute('r', r);
    circle.setAttribute('fill', m.color);
    circle.setAttribute('fill-opacity', '0.22');
    circle.setAttribute('stroke', m.color);
    circle.setAttribute('stroke-width', '2.5');
    circle.setAttribute('stroke-opacity', '0.8');
    svg.appendChild(circle);

    // Border ring for top models
    if (m.int >= 53) {
      const ring = document.createElementNS(svgNS, 'circle');
      ring.setAttribute('cx', cx);
      ring.setAttribute('cy', cy);
      ring.setAttribute('r', r + 4);
      ring.setAttribute('fill', 'none');
      ring.setAttribute('stroke', '#fff');
      ring.setAttribute('stroke-width', '2');
      ring.setAttribute('stroke-opacity', '0.3');
      ring.setAttribute('stroke-dasharray', '6,4');
      svg.appendChild(ring);
    }

    // Label
    const label = document.createElementNS(svgNS, 'text');
    label.setAttribute('x', cx);
    label.setAttribute('y', cy + 8);
    label.setAttribute('text-anchor', 'middle');
    label.setAttribute('fill', '#fff');
    label.setAttribute('font-size', m.int >= 50 ? '21' : '19');
    label.setAttribute('font-weight', m.int >= 53 ? '700' : '500');
    label.setAttribute('pointer-events', 'none');
    // Break long names
    const nm = m.short;
    if (nm.length > 14) {
      label.setAttribute('font-size', '17');
    }
    label.textContent = nm;
    svg.appendChild(label);

    // Price tag below
    const tag = document.createElementNS(svgNS, 'text');
    tag.setAttribute('x', cx);
    tag.setAttribute('y', cy + r + 28);
    tag.setAttribute('text-anchor', 'middle');
    tag.setAttribute('fill', '#939aa8');
    tag.setAttribute('font-size', '18');
    tag.setAttribute('font-weight', '500');
    tag.textContent = `$${m.price.toFixed(2)}`;
    svg.appendChild(tag);
  });

  // Legend
  const lx = pad.left + pw + 60;
  const ly = pad.top + 20;
  const legendSizes = [0.30, 2.00, 5.60, 10.00];
  legendSizes.forEach((p, i) => {
    const r = 20 + Math.sqrt((p - priceMin) / (priceMax - priceMin)) * 64;
    const cy = ly + 100 + i * 110;
    const circle = document.createElementNS(svgNS, 'circle');
    circle.setAttribute('cx', lx); circle.setAttribute('cy', cy);
    circle.setAttribute('r', r);
    circle.setAttribute('fill', '#636b7a');
    circle.setAttribute('fill-opacity', '0.2');
    circle.setAttribute('stroke', '#636b7a');
    circle.setAttribute('stroke-width', '1.5');
    svg.appendChild(circle);
    const text = document.createElementNS(svgNS, 'text');
    text.setAttribute('x', lx); text.setAttribute('y', cy + 8);
    text.setAttribute('text-anchor', 'middle');
    text.setAttribute('fill', '#939aa8');
    text.setAttribute('font-size', '18');
    text.setAttribute('font-weight', '500');
    text.textContent = `$${p.toFixed(2)}`;
    svg.appendChild(text);
  });
  const legTitle = document.createElementNS(svgNS, 'text');
  legTitle.setAttribute('x', lx); legTitle.setAttribute('y', ly + 40);
  legTitle.setAttribute('text-anchor', 'middle');
  legTitle.setAttribute('fill', '#636b7a');
  legTitle.setAttribute('font-size', '20');
  legTitle.setAttribute('font-weight', '600');
  legTitle.textContent = 'Cost';
  svg.appendChild(legTitle);

  container.appendChild(svg);
}

