const { chromium } = require('playwright');
const path = require('path');

(async () => {
  const browser = await chromium.launch({ headless: true });
  const context = await browser.newContext({
    viewport: { width: 3508, height: 5000 },
    deviceScaleFactor: 1,
  });
  const page = await context.newPage();

  const htmlPath = path.resolve('/app/output/poster.html');
  await page.goto(`file://${htmlPath}`, { waitUntil: 'networkidle' });

  // Wait for AntV Infographic to render (font loading + re-render)
  await page.waitForTimeout(4000);

  // Take full-page screenshot at 150 DPI (A1 width = 3508px)
  await page.screenshot({
    path: '/app/output/final_poster.png',
    fullPage: true,
    type: 'png',
