const { chromium } = require('playwright');
const path = require('path');

(async () => {
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage();

  // A1 portrait at 150 DPI
  await page.setViewportSize({ width: 3508, height: 4967 });

  const htmlPath = path.resolve('/app/output/poster.html');
  await page.goto(`file://${htmlPath}`, { waitUntil: 'networkidle' });

  // Wait for all AntV Infographic instances to render + font re-render
  await page.waitForTimeout(5000);

  // Check for rendering issues
  const hasContent = await page.evaluate(() => {
    const containers = document.querySelectorAll('.infographic-container svg');
    return containers.length;
  });
  console.log(`Infographic SVGs found: ${hasContent}`);

  await page.screenshot({
    path: '/app/output/final_poster.png',
    fullPage: false,
    type: 'png',
  });

  console.log('Poster saved to /app/output/final_poster.png (3508×4967)');
  await browser.close();
})();

