const { chromium } = require('playwright');
(async () => {
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage();
  await page.setViewportSize({ width: 3508, height: 4967 });
  await page.goto('file:///app/output/poster.html', { waitUntil: 'networkidle' });
  await page.waitForTimeout(5000);
  const info = await page.evaluate(() => {
    const svgs = document.querySelectorAll('svg');
    const infContainers = document.querySelectorAll('.infographic-container');
    const bubbleSVG = document.querySelector('#bubble-chart-container svg');
    return {
      svgCount: svgs.length,
      infContainers: infContainers.length,
      bubbleChart: bubbleSVG ? { width: bubbleSVG.getAttribute('width'), height: bubbleSVG.getAttribute('height'), childCount: bubbleSVG.childElementCount } : null,
      bodySize: document.body.scrollWidth + 'x' + document.body.scrollHeight,
      totalText: document.body.innerText.substring(0, 500)
    };
  });
  console.log(JSON.stringify(info, null, 2));
  await browser.close();
})();
" 2>&1

